// vb-3l40a: Direct shard boundary validation test.
// Proves that contracts validated at the shard entry methods before
// any run admission, header, or journal mutation when enqueued directly.

#[test]
fn shard_boundary_validates_fabricated_id_before_admission() {
    use crate::shard::ShardCommand;
    use vb_core::ids::ActionId;

    let mut shard = contract_validation_test_shard();
    let workflow = contract_validation_do_workflow(0);

    let run = RunId::new(100);
    let caps = CapabilitySet::empty();

    // Contract with ID 999 at index 0 - fabricated ID.
    let contract = contract_validation_make_contract(999, "fabricated")
        .expect("test contract must be valid");
    let action_contracts: Box<[vb_core::action::ActionContract]> = Box::from([contract]);

    // Enqueue directly to shard, bypassing Runtime preflight.
    let _ = shard.enqueue(ShardCommand::SubmitWithContracts {
        run,
        workflow: workflow.clone(),
        caps,
        action_contracts,
    });

    // Drive the shard to process the command. Tick fails with validation error.
    let tick_result = shard.tick();
    assert!(
        tick_result.is_err(),
        "tick should fail with validation error"
    );
    assert!(
        matches!(
            tick_result,
            Err(RuntimeError::ContractValidationError { .. })
        ),
        "should be ContractValidationError: {:?}",
        tick_result
    );

    // Run should NOT exist - validation must reject before admission.
    assert!(
        !shard.run_state_contains(run),
        "fabricated contract must be rejected before run admission"
    );
}

#[test]
fn shard_boundary_accepts_valid_contract() {
    use crate::shard::ShardCommand;

    let mut shard = contract_validation_test_shard();
    let workflow = contract_validation_do_workflow(0);

    let run = RunId::new(101);
    let caps = CapabilitySet::empty();

    // Valid contract with ID 0 at index 0.
    let contract = contract_validation_make_contract(0, "valid_action")
        .expect("test contract must be valid");

    let action_contracts: Box<[vb_core::action::ActionContract]> = Box::from([contract]);
    // Enqueue directly to shard.
    let _ = shard.enqueue(ShardCommand::SubmitWithContracts {
        run,
        workflow: workflow.clone(),
        caps,
        action_contracts,
    });

    // Drive the shard to process the command. Tick succeeds.
    let tick_result = shard.tick();
    assert!(
        tick_result.is_ok(),
        "tick should succeed for valid contract: {:?}",
        tick_result
    );



    // Run should exist in run state or terminal runs.
    assert!(
        shard.run_state_contains(run) || shard.terminal_runs_contains(run),
        "valid contract must be accepted at shard boundary"
    );
}

